import {builderKey,deviceTypes,blankNetwork,exampleNetwork,newDevice,validateNetwork,parseDesign,parseInterfaces,parseRules,parseRoutes,removeDevice,traceNetwork} from './network-builder-core.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
export function initializeNetworkBuilder({onOpen,onClose,onRender}){
 let design,storage=true;try{const saved=localStorage.getItem(builderKey);design=saved?parseDesign(saved):exampleNetwork();}catch{design=exampleNetwork();storage=false;}
 let selected=design.nodes[0]?.id||'',open=false,result=null,index=0;const undo=[];
 const message=t=>{$('net-message').textContent=t;};
 const save=()=>{try{localStorage.setItem(builderKey,JSON.stringify(design));storage=true;}catch{storage=false;}$('net-save').textContent=storage?'Design saves in this browser. Export JSON for a portable copy.':'Browser storage unavailable. Export JSON to keep this design.';};
 function commit(candidate){try{const clean=validateNetwork(candidate);undo.push(JSON.stringify(design));if(undo.length>20)undo.shift();design=clean;result=null;index=0;if(!design.nodes.some(n=>n.id===selected))selected=design.nodes[0]?.id||'';save();render();message('Design updated. Run the trace again to check the new topology.');return true;}catch(e){message(e.message);return false;}}
 function options(id,all=design.nodes){const old=$(id).value;$(id).replaceChildren(...all.map(n=>{const o=el('option',n.name);o.value=n.id;return o;}));$(id).value=all.some(n=>n.id===old)?old:all[0]?.id||'';}
 function fill(){const n=design.nodes.find(n=>n.id===selected);$('net-device-editor').hidden=!n;if(!n)return;$('net-name').value=n.name;$('net-kind').value=n.type;$('net-interfaces').value=n.interfaces.join(', ');$('net-gateway').value=n.gateway;$('net-listener').value=n.port;$('net-protocol').value=n.protocol;$('net-x').value=n.x;$('net-z').value=n.z;$('net-routes').value=n.routes.map(r=>r.cidr+' via '+r.gateway).join('\n');$('net-rules').value=n.rules.map(r=>`${r.protocol} ${r.port??'any'} ${r.source}`).join('\n');$('net-stateful').checked=n.stateful;$('net-backend-port').value=n.backendPort;const none=el('option','No backend');none.value='';$('net-backend').replaceChildren(none,...design.nodes.filter(p=>p.id!==n.id&&!['router','firewall'].includes(p.type)).map(p=>{const o=el('option',p.name);o.value=p.id;return o;}));$('net-backend').value=n.backend;$('net-router-settings').hidden=!['router','firewall'].includes(n.type);$('net-firewall-settings').hidden=n.type!=='firewall';$('net-proxy-settings').hidden=n.type!=='load-balancer';}
 function render(){options('net-devices');$('net-devices').value=selected;for(const id of ['net-link-from','net-link-to','net-source','net-destination'])options(id);$('net-links').replaceChildren(...design.links.map((l,i)=>{const li=el('li');li.append(el('span',design.nodes.find(n=>n.id===l.from).name+' ↔ '+design.nodes.find(n=>n.id===l.to).name+' · adjacency'));const b=el('button','Remove link');b.addEventListener('click',()=>commit({...design,links:design.links.filter((_,j)=>j!==i)}));li.append(b);return li;}));fill();$('net-undo').disabled=!undo.length;$('net-prev').disabled=!result||index===0;$('net-next').disabled=!result||index===result.steps.length-1;$('net-result').textContent=result?(result.ok?'SIMULATED CHECKS PASSED · ':'SIMULATED BLOCK · ')+result.summary:'Connect devices, then trace a request. Links describe adjacency, not new application servers.';const step=result?.steps[index];$('net-step').textContent=step?`${index+1}/${result.steps.length} · ${step.title}\n${step.text}\n${step.packet}`:'';$('net-node-count').textContent=`${design.nodes.length}/24 devices · ${design.links.length}/48 links`;$('net-trace-steps').replaceChildren(...(result?.steps||[]).map((s,i)=>{const li=el('li'),b=el('button',`${i+1}. ${s.title}`);b.addEventListener('click',()=>{index=i;render();});li.append(b);return li;}));if(open)onRender(design,selected,step);}
 function select(id){if(!design.nodes.some(n=>n.id===id))return;selected=id;render();}
 function drawMap(host){const NS='http://www.w3.org/2000/svg',make=(tag,attrs={},text)=>{const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;};const svg=make('svg',{viewBox:'0 0 1000 700',role:'group','aria-label':'Your custom network. Select a device to edit it.'}),point=n=>({x:500+n.x*10,y:350+n.z*7});for(const l of design.links){const a=point(design.nodes.find(n=>n.id===l.from)),b=point(design.nodes.find(n=>n.id===l.to));svg.append(make('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:'#638baf','stroke-width':3}));}const s=result?.steps[index];if(s&&s.from!==s.to){const a=point(design.nodes.find(n=>n.id===s.from)),b=point(design.nodes.find(n=>n.id===s.to));svg.append(make('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:s.blocked?'#ff879d':s.phase==='response'?'#a7edb3':'#6be5ff','stroke-width':6}));svg.append(make('text',{x:(a.x+b.x)/2,y:(a.y+b.y)/2-15,fill:'#f7eacb','font-size':13,'text-anchor':'middle'},s.phase+' → '+design.nodes.find(n=>n.id===s.to).name));}for(const n of design.nodes){const p=point(n),g=make('g',{tabindex:0,role:'button','aria-label':'Edit '+n.name});g.append(make('rect',{x:p.x-70,y:p.y-30,width:140,height:60,rx:10,fill:n.id===selected?'#375b6c':'#20334f',stroke:n.id===s?.from&&s.blocked?'#ff879d':'#92b9d6','stroke-width':2}),make('text',{x:p.x,y:p.y-6,fill:'#e4f7ff','font-size':13,'text-anchor':'middle'},n.name.slice(0,20)),make('text',{x:p.x,y:p.y+17,fill:'#abc7d6','font-size':10,'text-anchor':'middle'},n.type+' · '+n.interfaces[0]));g.addEventListener('click',()=>select(n.id));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(n.id);}});svg.append(g);}const p=el('p',s?s.packet:'Lines are adjacency links. Run a trace to see the packet tuple and request/response direction.');host.replaceChildren(svg,p);}
 for(const id of ['net-add-kind','net-kind'])$(id).replaceChildren(...deviceTypes.map(t=>{const o=el('option',t);o.value=t;return o;}));$('net-add-kind').value='app';$('net-trace-protocol').value='TCP';$('net-trace-port').value='8080';
 $('network-build').addEventListener('click',()=>{open=true;$('network-panel').hidden=false;onOpen();save();render();message('1. Add/edit devices. 2. Connect neighbors. 3. Trace and fix the first failing boundary.');});$('net-close').addEventListener('click',()=>{open=false;$('network-panel').hidden=true;onClose();});
 $('net-add').addEventListener('click',()=>{const next=Math.max(0,...design.nodes.map(n=>Number(n.id.slice(1))))+1;if(next>99999)return message('Device ID limit reached.');const n=newDevice('n'+next,$('net-add-kind').value,next);if(commit({...design,nodes:[...design.nodes,n]})){selected=n.id;render();}});
 $('net-devices').addEventListener('change',()=>select($('net-devices').value));$('net-kind').addEventListener('change',()=>{const type=$('net-kind').value;$('net-router-settings').hidden=!['router','firewall'].includes(type);$('net-firewall-settings').hidden=type!=='firewall';$('net-proxy-settings').hidden=type!=='load-balancer';});
 $('net-apply').addEventListener('click',()=>{try{const n={...design.nodes.find(n=>n.id===selected),name:$('net-name').value,type:$('net-kind').value,interfaces:parseInterfaces($('net-interfaces').value),gateway:$('net-gateway').value.trim(),port:Number($('net-listener').value),protocol:$('net-protocol').value,x:Number($('net-x').value),z:Number($('net-z').value),routes:parseRoutes($('net-routes').value),rules:parseRules($('net-rules').value),stateful:$('net-stateful').checked,backend:$('net-backend').value,backendPort:Number($('net-backend-port').value)};commit({...design,nodes:design.nodes.map(p=>p.id===selected?n:p)});}catch(e){message(e.message);}});
 $('net-delete').addEventListener('click',()=>{try{commit(removeDevice(design,selected));}catch(e){message(e.message);}});$('net-connect').addEventListener('click',()=>commit({...design,links:[...design.links,{from:$('net-link-from').value,to:$('net-link-to').value}]}));
 $('net-template').addEventListener('click',()=>{commit(exampleNetwork());$('net-source').value='n1';$('net-destination').value='n3';$('net-trace-port').value='8080';});$('net-template-proxy').addEventListener('click',()=>{commit(exampleNetwork(true));$('net-source').value='n1';$('net-destination').value='n4';$('net-trace-port').value='443';});$('net-empty').addEventListener('click',()=>commit(blankNetwork()));$('net-undo').addEventListener('click',()=>{if(!undo.length)return;design=parseDesign(undo.pop());selected=design.nodes[0]?.id||'';result=null;save();render();message('Previous design restored.');});
 $('net-run').addEventListener('click',()=>{try{result=traceNetwork(design,{from:$('net-source').value,to:$('net-destination').value,port:Number($('net-trace-port').value),protocol:$('net-trace-protocol').value});index=0;render();message('Trace complete. Use Next to inspect each routing, policy and return-path check.');}catch(e){message(e.message);}});$('net-prev').addEventListener('click',()=>{if(index>0){index--;render();}});$('net-next').addEventListener('click',()=>{if(result&&index<result.steps.length-1){index++;render();}});
 $('net-export').addEventListener('click',()=>{$('net-json').value=JSON.stringify(design,null,2);const url=URL.createObjectURL(new Blob([$('net-json').value],{type:'application/json'}));const a=el('a');a.href=url;a.download='my-devops-network.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);message('JSON download prepared. The same text is available below for copying or importing.');});$('net-import').addEventListener('click',()=>{try{commit(parseDesign($('net-json').value));}catch(e){message('Import rejected: '+e.message);}});
 options('net-source');options('net-destination');$('net-source').value='n1';$('net-destination').value=design.nodes.some(n=>n.id==='n3')?'n3':design.nodes.at(-1)?.id||'';
 return {isOpen:()=>open,select,drawMap,close(){if(!open)return;open=false;$('network-panel').hidden=true;onClose();},refresh(){if(open)render();},getDesign:()=>JSON.parse(JSON.stringify(design)),getView:()=>({design,selected,step:result?.steps[index]})};
}
